      File.open(metadata_file, "w") do |file|
        file.puts Marshal.dump(:foo => "bar")[0, 5]
      end

      @regenerator = Regenerator.new(@site)
      assert_equal({}, @regenerator.metadata)
    end

    # Methods

    should "be able to add a path to the metadata" do
