      refute @regenerator.modified?(@path)
      refute @regenerator.cache[@path]
      refute @regenerator.modified?(@path)
    end

    should "regenerate if path in not in metadata" do
      @regenerator.clear
      @regenerator.add(@path)

      assert @regenerator.modified?(@path)
    end

